mapper.update:
/* LeavePolicyMapper.deactivatePolicy */
UPDATE TB_LEAVE_POLICY
   SET USE_YN      = 'N'
     , UPDATE_NO   = #{updateBy}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND POLICY_SEQ = #{policySeq}
   AND USE_YN = 'Y'

mapper.insert:
/* LeavePolicyMapper.insertPolicy */
INSERT INTO TB_LEAVE_POLICY (
      CMPNY_CD
    , POLICY_PRESET
    , AXIS1_GRANT_BASE
    , AXIS2_FISCAL_START_MM
    , AXIS2_FISCAL_START_DD
    , AXIS3_FIRST_YEAR_METHOD
    , AXIS3_PREGRANT_YN
    , AXIS4_PRORATE_ROUNDING
    , AXIS5_TENURE_MODE
    , AXIS5_START_YEAR
    , AXIS5_INTERVAL
    , AXIS5_MAX_DAYS
    , AXIS6_VALIDITY_MONTHS
    , AXIS7_USE_PROMOTION
    , STATUTORY_AUTO_GRANT_YN
    , APRV_USE_YN
    , USE_YN
    , APPLY_FROM_DATE
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      #{cmpnyCd}
    , #{policyPreset}
    , #{axis1GrantBase}
    , #{axis2FiscalStartMm}
    , #{axis2FiscalStartDd}
    , #{axis3FirstYearMethod}
    , #{axis3PregrantYn}
    , #{axis4ProrateRounding}
    , #{axis5TenureMode}
    , #{axis5StartYear}
    , #{axis5Interval}
    , #{axis5MaxDays}
    , #{axis6ValidityMonths}
    , #{axis7UsePromotion}
    /* 소정-05: 서비스에서 Y/N 정규화(비정상/미지정 → 'Y' = 기존 동작) 후 전달 */
    , #{statutoryAutoGrantYn}
    , #{aprvUseYn}
    , #{useYn}
    , #{applyFromDate}
    , #{insertNo}
    , NOW()
    , #{updateNo}
    , NOW()
)

/* LeavePolicyMapper.insertUsagePolicy */
INSERT INTO TB_LEAVE_USAGE_POLICY (
      POLICY_SEQ
    , CMPNY_CD
    , USAGE_UNIT
    , ALLOW_QUARTER
    , ALLOW_REMNANT_ROUND_UP
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      #{policySeq}
    , #{cmpnyCd}
    , #{usageUnit}
    , #{allowQuarter}
    , #{allowRemnantRoundUp}
    , #{insertNo}
    , NOW()
    , #{updateNo}
    , NOW()
)

/* LeavePolicyMapper.insertPolicyHistory */
INSERT INTO TB_LEAVE_POLICY_HISTORY (
      HIST_ID
    , CMPNY_CD
    , POLICY_SEQ
    , CHANGE_TYPE
    , PREV_SNAPSHOT
    , NEW_SNAPSHOT
    , CHANGE_REASON
    , IMPACT_SUMMARY
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{histId}
    , #{cmpnyCd}
    , #{policySeq}
    , #{changeType}
    , #{prevSnapshot}
    , #{newSnapshot}
    , #{changeReason}
    , #{impactSummary}
    , #{insertNo}
    , NOW()
)

mapper.select:
/* LeavePolicyMapper.countPolicyHistory */
SELECT COUNT(*)
  FROM TB_LEAVE_POLICY_HISTORY
 WHERE CMPNY_CD = #{cmpnyCd}

/* LeavePolicyMapper.selectMaxPolicySeq */
SELECT MAX(POLICY_SEQ)
  FROM TB_LEAVE_POLICY
 WHERE CMPNY_CD = #{cmpnyCd}
